    @EventHandler( payloadType=CreatePlantEvent.class )
    public void handle( CreatePlantEvent event) {
	    LOGGER.info("handling CreatePlantEvent - " + event );
	    Plant entity = new Plant();
            entity.setPlantId( event.getPlantId() );
            entity.setName( event.getName() );
            entity.setPlantCode( event.getPlantCode() );
            entity.setAddress( event.getAddress() );
            entity.setTimeZone( event.getTimeZone() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPlant( entity );
    }

    /*
     * @param	event UpdatePlantEvent
     */
    @EventHandler( payloadType=UpdatePlantEvent.class )
    public void handle( UpdatePlantEvent event) {
    	LOGGER.info("handling UpdatePlantEvent - " + event );
    	
	    Plant entity = new Plant();
            entity.setPlantId( event.getPlantId() );
            entity.setName( event.getName() );
            entity.setPlantCode( event.getPlantCode() );
            entity.setAddress( event.getAddress() );
            entity.setTimeZone( event.getTimeZone() );
            entity.setEnterprise( event.getEnterprise() );
            entity.setProductionLines( event.getProductionLines() );
            entity.setWorkCenters( event.getWorkCenters() );
            entity.setWarehouses( event.getWarehouses() );
            entity.setAssets( event.getAssets() );
            entity.setProductionSchedules( event.getProductionSchedules() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindPlant( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPlant( entity );        
    }
    
