    /**
     * Method to retrieve the Plant via an PlantPrimaryKey.
     * @param 	id Long
     * @return 	Plant
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Plant handle( FindPlantQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPlantId() );
    }
    
    /**
     * Method to retrieve a collection of all Plants
     *
     * @param	query	FindAllPlantQuery 
     * @return 	List<Plant> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Plant> handle( FindAllPlantQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPlant,
 * but only if the id matches
 *
 * @param		entity	Plant
 */
	protected void emitFindPlant( Plant entity ) {
		LOGGER.info("handling emitFindPlant" );
		
	    queryUpdateEmitter.emit(FindPlantQuery.class,
	                            query -> query.getFilter().getPlantId().equals(entity.getPlantId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPlant
	 * 
	 * @param		entity	Plant
	 */
	protected void emitFindAllPlant( Plant entity ) {
		LOGGER.info("handling emitFindAllPlant" );
		
	    queryUpdateEmitter.emit(FindAllPlantQuery.class,
	                            query -> true,
	                            entity);
	}

